def train(model, X, Y, steps, lr):
    losses = []
    for k in range(steps + 1):
        loss = sum(((model(x) - y) ** 2 for x, y in zip(X, Y)), Value(0.0))
        losses.append(loss.data)
        if k == steps:
            break
        for p in model.parameters():
            p.grad = 0.0
        loss.backward()
        for p in model.parameters():
            p.data -= lr * p.grad
    return losses

